void UAlsAnimationInstance::RefreshVelocityBlend()
{
	// Calculate and interpolate the velocity blend amounts. This value represents the velocity amount of
	// the character in each direction (normalized so that diagonals equal 0.5 for each direction) and is
	// used in a blend multi node to produce better directional blending than a standard blend space.

	auto& VelocityBlend{GroundedState.VelocityBlend};

	auto VelocityDirection{GetVelocity()};
	auto TargetVelocityBlend{FVector3f::ZeroVector};

	if (VelocityDirection.Normalize())
	{
		TargetVelocityBlend = VelocityDirection /
		                      (FMath::Abs(VelocityDirection.X) + FMath::Abs(VelocityDirection.Y) + FMath::Abs(VelocityDirection.Z));
	}

inline bool TVector<T>::Normalize(T Tolerance)
{
    const T SquareSum = X*X + Y*Y + Z*Z;
    if(SquareSum > Tolerance)
    {
        const T Scale = FMath::InvSqrt(SquareSum);
        X *= Scale; Y *= Scale; Z *= Scale;
        return true;
    }
    return false;

fn velocity_local_f64(world_velocity: Vec3, character_rotation: Quat) -> Vec3 {
    (character_rotation.as_dquat().inverse() * world_velocity.as_dvec3()).as_vec3()
}

fn source_scalar_divide(vector: Vec3, divisor: f32) -> Vec3 {
    vector * divisor.recip()
}

pub fn velocity_blend_direction(world_velocity: Vec3, character_rotation: Quat) -> Vec3 {
    let local = velocity_local_f64(world_velocity, character_rotation);
    if local.length_squared() > 1e-12 {
        source_scalar_divide(local, local.abs().element_sum())
    } else {
        Vec3::ZERO
